 "content": "def transform(grid):
    """Return the cellwise intersection of equal-height panels above/below a solid divider."""
    h, w = len(grid), len(grid[0])
    divider = next((r for r, row in enumerate(grid)
                    if row and all(v == row[0] for v in row)), None)
    if divider is None:
        raise ValueError("no solid horizontal divider")
    top, bottom = grid[:divider], grid[divider + 1:]
    if len(top) != len(bottom):
        raise ValueError("panels must have equal height")
    return [[2 if a != 0 and b != 0 else 0 for a, b in zip(rt, rb)]
            for rt, rb in zip(top, bottom)]

